package store

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLoad(t *testing.T) {
	d := t.TempDir()
	p := filepath.Join(d, "value.txt")
	if err := os.WriteFile(p, []byte("ok"), 0600); err != nil { t.Fatal(err) }
	got, err := Load(p)
	if err != nil || got != "ok" { t.Fatalf("got %q, %v", got, err) }
}

func TestLoadMissingReturnsError(t *testing.T) {
	if _, err := Load(filepath.Join(t.TempDir(), "missing")); err == nil {
		t.Fatal("expected an error")
	}
}
